input.command:
python3 -c "
import json
d=json.load(open('/tmp/env.json'))
m={}
for it in d:
    e=it.get('envVar') or {}
    m[e.get('key')]=e.get('value') or ''
hits=[k for k in m if 'ACCESS_TOKEN' in k or ('SUPABASE' in k and 'TOKEN' in k)]
for k in hits:
    v=m[k]
    print(k, 'len', len(v), 'prefix', v[:4]+'...')
open('/tmp/sbtok.txt','w').write(m.get('IVX_OWNER_SUPABASE_ACCESS_TOKEN') or m.get('SUPABASE_ACCESS_TOKEN') or '')
" 2>&1; echo "---"; wc -c < /tmp/sbtok.txt

